}

// ---------------------------------------------------------------- layout

export function runnerRoot(env: NodeJS.ProcessEnv = process.env): string {
  return path.join(env.NEXUS_STATE_DIR || path.join(os.homedir(), ".nexus"), "runner");
}

export interface RunnerPaths {
  root: string;
  guard: string;
  runnerJson: string;
  inbox: string;
  rejected: string;
  jobs: string;
  request(requestId: string): string;
  jobDir(id: string): string;
  job(id: string): string;
  spec(id: string): string;
  workerGuard(id: string): string;
  workerJson(id: string): string;
  events(id: string): string;
  stderr(id: string): string;
