    ["*/0 * * * *", /step of 0/],
    ["60 * * * *", /outside 0-59/],
    ["* 24 * * *", /outside 0-23/],
    ["* * 0 * *", /outside 1-31/],
    ["* * 32 * *", /outside 1-31/],
    ["* * * 13 *", /outside 1-12/],
    ["* * * 0 *", /outside 1-12/],
    ["* * * * 8", /outside 0-7/],
    ["* * * JAN *", /names such as MON or JAN/],
    ["* * * * MON", /names such as MON or JAN/],
    ["@daily", /shortcuts/],
    ["@reboot", /shortcuts/],
    ["5-1 * * * *", /backwards/],
    ["1-2-3 * * * *", /not a range/],
    ["1/5 * * * *", /needs '\*' or a range/],
    ["*/100 * * * *", /larger than/],
    ["0-5/9 * * * *", /larger than/],
    ["1,,2 * * * *", /empty list item/],
    ["*/5/2 * * * *", /more than one/],
    ["-1 * * * *", /not a number/],
    ["1.5 * * * *", /not a number/],
    ["0x10 * * * *", /not a number/],
    [" * * * * *", /single spaces/],
    ["*  * * * *", /single spaces/],
    ["*\t* * * *", /single spaces|5 fields/],
    ["* * * * *\n", /single spaces/],
